    /// <summary>One location, whose body is written out in full by the caller.</summary>
    private static World WithLocationBody(string body) => World.FromJson(
        "{ \"spawnLocation\": 1, \"locations\": [ { \"index\": 1, \"name\": \"A\", "
        + "\"isExit\": true, " + body + " } ] }");

    private static World WithInteraction(string interaction) =>
        WithLocationBody("\"interactions\": [ " + interaction + " ]");

    private static string Complaint(IEnumerable<ValidationIssue> issues, string key) =>
        issues.First(issue => issue.Message.Contains($"sets '{key}'")).Message;

    // A key the loader has never heard of is dropped without a word. These four
    // say that it is no longer dropped in silence — because the silence is the
    // whole injury: the file goes on reading, to whoever wrote it, as intended.

    [Fact]
    public void AKeyNothingReadsIsRejected()
    {
        var issues = WorldValidator.Validate(WithInteraction(
            "{ \"interactionId\": \"x\", \"triggers\": [\"*x*\"], \"onlyonce\": true, \"actions\": [] }"));

        Assert.True(WorldValidator.HasErrors(issues));
        Assert.Contains("dropped in silence", Complaint(issues, "onlyonce"));
    }

    [Fact]
    public void AndTheRejectionSaysWhatIsReadInstead()
    {
        var issues = WorldValidator.Validate(WithInteraction(
            "{ \"interactionId\": \"x\", \"triggers\": [\"*x*\"], \"onlyonce\": true, \"actions\": [] }"));
        var complaint = Complaint(issues, "onlyonce");

        Assert.Contains("once", complaint);
        Assert.Contains("ifNot", complaint);
    }

    [Fact]
    public void ANearMissIsNamedOutright()
    {
        var issues = WorldValidator.Validate(WithInteraction(
            "{ \"interactionId\": \"x\", \"trigger\": [\"*x*\"], \"actions\": [] }"));

        Assert.Contains("Did you mean 'triggers'?", Complaint(issues, "trigger"));
    }

    [Fact]
    public void ANoteToTheNextPersonIsLeftAlone()
    {
        var issues = WorldValidator.Validate(WithInteraction(
            "{ \"interactionId\": \"x\", \"triggers\": [\"*x*\"], "
            + "\"_why\": \"the bell has to stay reachable\", \"actions\": [] }"));

        Assert.False(WorldValidator.HasErrors(issues));
    }

    [Fact]
    public void ActionsAndLocationsAndConnectionsAreCheckedToo()
    {
        var action = WorldValidator.Validate(WithInteraction(
            "{ \"interactionId\": \"x\", \"triggers\": [\"*x*\"], \"actions\": "
            + "[ { \"action\": \"describe\", \"parameters\": [\"hello\"], \"scoped\": \"player\" } ] }"));
        Assert.Contains("scope", Complaint(action, "scoped"));

