        Assert.True(WorldValidator.HasErrors(location));

        var connections = WorldValidator.Validate(WithLocationBody(
            "\"connections\": { \"up\": 2 }"));
        Assert.Contains("What is read here: north, east, south, west", Complaint(connections, "up"));
    }
