using Og.Core.Runtime;

namespace Og.Core.Tests;

/// <summary>
/// The one instrument the caretaker does not otherwise have.
///
/// `play` returns you to your most recent living character, so every hand-test of
/// this world is run by somebody who has already done half of it. On 2026-09-21
/// that cost a real piece of writing: a veteran's line was read by the veteran,
/// mistaken for a lie told to a beginner, and deleted.
///
/// WorldFixture deliberately does not read the authored map, and is right not to
/// — those tests check the engine, which must hold for any world. This one is the
/// opposite on purpose. It stands in the real map as somebody who has done
/// nothing and asks the only question such a person has: if I type the words this
/// room advertises, does the room answer me at all?
///
/// A phrase only a gated variant knows is a phrase the beginner gets silence for,
/// and silence is the answer that teaches them the room does not care.
/// </summary>
public class StrangerTests
{
    private static string MapPath()
    {
        var directory = new DirectoryInfo(AppContext.BaseDirectory);

        while (directory is not null)
        {
            var candidate = Path.Combine(directory.FullName, "world", "maps", "starter.json");

            if (File.Exists(candidate))
            {
                return candidate;
            }

            directory = directory.Parent;
        }

        // Never skip quietly. A test that passes because it could not find the
        // thing it checks is a false success, which is worse than no test.
        throw new FileNotFoundException(
            $"Could not find world/maps/starter.json above {AppContext.BaseDirectory}");
    }

    /// <summary>What a player would have to type to set a trigger off.</summary>
    private static IEnumerable<string> Phrases(Interaction interaction) =>
        interaction.Triggers
            .Select(trigger => TriggerMatcher.Normalize(trigger.Replace("*", " ")))
            .Where(phrase => phrase.Length > 0);

    private static void EverySentenceThisMapOffersIsAnswered(params string[] worldConditions)
    {
        var world = World.Load(MapPath());

        foreach (var condition in worldConditions)
        {
            world.Conditions.Add(condition);
        }

        // A character with nothing: no conditions, nothing fired, nothing done.
        var (engine, _) = WorldFixture.NewEngine();
        var (session, _) = WorldFixture.Join(engine, "stranger");

        var silent = new List<string>();

        foreach (var location in world.Locations.OrderBy(location => location.Id))
        {
            var reachable = location.Interactions
                .Where(interaction => interaction.IsEligible(world, session))
                .ToList();

            foreach (var phrase in location.Interactions.SelectMany(Phrases).Distinct().Order())
            {
                if (reachable.Any(interaction => interaction.MatchesTrigger(phrase)))
                {
                    continue;
                }

                var offeredBy = location.Interactions
                    .First(interaction => Phrases(interaction).Contains(phrase))
                    .Id ?? "(unnamed)";

                silent.Add($"location {location.Id} answers nothing to \"{phrase}\" (offered by '{offeredBy}')");
            }
        }

        Assert.True(silent.Count == 0,
            $"Somebody who has done nothing gets silence for {silent.Count} phrase(s) this map "
            + $"advertises elsewhere:{Environment.NewLine}  "
            + string.Join(Environment.NewLine + "  ", silent));
    }

    [Fact]
    public void AStrangerWhoHasDoneNothingIsAnsweredEverywhere() =>
        EverySentenceThisMapOffersIsAnswered();

    [Fact]
    public void AndSoIsOneWhoArrivesLongAfterTheWaveCameDown() =>
        EverySentenceThisMapOffersIsAnswered("wave_fallen", "lamp_lit");
}

