using Og.Core.Runtime;

namespace Og.Core.Tests;

/// <summary>
/// The beginner's view, which nobody standing in this world can take any more.
/// `play` returns the caretaker to their most recent living character, and that
/// character has done everything — so the one experience that is never checked
/// by hand is the only one every arrival actually has.
///
/// The validator takes it instead. These say it takes it correctly.
///
/// The first version of this file read world/maps/starter.json and asserted
/// directly. It found real gaps and was still the wrong shape: a failing test
/// truncates its own output, so it could tell me something was wrong and not
/// what. `validate` hands back every issue in full. The check moved; the
/// question did not.
/// </summary>
public class StrangerTests
{
    private static World Room(string interactions) => World.FromJson(
        "{ \"spawnLocation\": 1, \"locations\": [ { \"index\": 1, \"name\": \"A\", "
        + "\"isExit\": true, \"interactions\": [ " + interactions + " ] } ] }");

    private static IEnumerable<string> Silences(World world) =>
        WorldValidator.Validate(world)
            .Where(issue => issue.Message.Contains("gets silence"))
            .Select(issue => issue.Message);

    private const string Gated =
        "{ \"interactionId\": \"veteran\", \"if\": [\"has_left\"], "
        + "\"triggers\": [\"the boat\", \"how do i get out\"], "
        + "\"actions\": [ { \"action\": \"describe\", \"parameters\": [\"You went, and came back.\"] } ] }";

    private const string Setter =
        "{ \"interactionId\": \"setter\", \"triggers\": [\"go\"], \"actions\": "
        + "[ { \"action\": \"addCondition\", \"parameters\": [\"has_left\"] } ] }";

    [Fact]
    public void APhraseOnlyAGatedBranchAnswersIsReported()
    {
        var silences = Silences(Room(Gated + ", " + Setter)).ToList();

        Assert.Contains(silences, message => message.Contains("\"how do i get out\""));
        Assert.Contains(silences, message => message.Contains("'veteran'"));
    }

    [Fact]
    public void AnUngatedFallbackUnderneathSettlesIt()
    {
        var fallback =
            "{ \"interactionId\": \"anybody\", \"triggers\": [\"*the boat*\", \"*how do i get out*\"], "
            + "\"actions\": [ { \"action\": \"describe\", \"parameters\": [\"It is tied.\"] } ] }";

        Assert.Empty(Silences(Room(Gated + ", " + fallback + ", " + Setter)));
    }

    /// <summary>
    /// A player carrying nothing cannot be excluded by an 'ifNot', so an ifNot-only
    /// branch is one a beginner reaches. Treating it as gated would bury the real
    /// warnings under a pile of false ones.
    /// </summary>
    [Fact]
    public void AnIfNotBranchIsSomethingABeginnerCanReach()
    {
        var ifNotOnly =
            "{ \"interactionId\": \"before\", \"ifNot\": [\"has_left\"], \"triggers\": [\"the boat\"], "
            + "\"actions\": [ { \"action\": \"describe\", \"parameters\": [\"It is tied.\"] } ] }";

        Assert.Empty(Silences(Room(ifNotOnly + ", " + Setter)));
    }

    /// <summary>It is a missing kindness, not a lie. It must never block a deploy.</summary>
    [Fact]
    public void AndItIsOnlyEverAWarning()
    {
        var issues = WorldValidator.Validate(Room(Gated + ", " + Setter));

        Assert.NotEmpty(Silences(Room(Gated + ", " + Setter)));
        Assert.False(WorldValidator.HasErrors(issues));
    }
}

