[Fact]
public void TwinsWithNoConditionsAreNotToldToReorderThemselves()
{
    var issues = WorldValidator.Validate(WithLocationBody(
        "\"interactions\": [ "
        + "{ \"interactionId\": \"first\", \"triggers\": [\"*the heron*\"], \"actions\": [] }, "
        + "{ \"interactionId\": \"second\", \"triggers\": [\"the heron\"], \"actions\": [] } ]"));

    var shadow = issues.First(issue => issue.Message.Contains("always wins")).Message;

    Assert.Contains("unreachable", shadow);
    Assert.DoesNotContain("Put the conditional one first", shadow);
}

